from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from .models import CustomServiceToken

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def revoke_service_token(request):
    token_hash = request.data.get('token_hash')
    if not token_hash:
        return Response({'error': 'token_hash required'}, status=status.HTTP_400_BAD_REQUEST)

    deleted_count, _ = CustomServiceToken.objects.filter(
        token_hash=token_hash,
        team__organization=request.user.organization
    ).delete()
    if not deleted_count:
        return Response({'error': 'Token not found or unauthorized'}, status=status.HTTP_404_NOT_FOUND)

    return Response({'status': 'revoked', 'token_hash': token_hash})
